from pathlib import Path
import json,hashlib
import numpy as np
r=Path(__file__).resolve().parent;prefix=r/'final_verified';roi=np.load(r/'input_with_background/roi.npz');components=np.load(r/'final_components.npz');stats=json.load(open(str(prefix)+'.stats.json'));meta=json.load(open(r/'input_with_background_metadata.json'))
ids=roi['original_ids'];coords=roi['coords'];reference=roi['reference_id'];background=roi['background'];n=len(ids);classes=np.full(n,-1,np.int8);classes[reference>=0]=0;clusters=np.full(n,-1,np.int32);is_input=(reference<0)&~background
pairs=components['pairs'];nodes=components['nodes'];counts=components['counts'];selected=nodes[counts>=200];sp=pairs[np.isin(pairs[:,1],selected)];cover=np.bincount(sp[:,0],minlength=len(components['site_ids']));assert not np.any(cover>1),'Retained coverage overlaps; refusal rather than silently assigning points'
site_ids=components['site_ids'];order=np.argsort(ids);rows=order[np.searchsorted(ids[order],site_ids[sp[:,0]])];assert np.array_equal(ids[rows],site_ids[sp[:,0]]);assert np.all(is_input[rows]);classes[rows]=1;clusters[rows]=sp[:,1]
origin=np.array(meta['quantization']['origin_m']);unit=meta['quantization']['unit_m'];q=np.rint((coords-origin)/unit).astype(np.int32);assert np.all((q[is_input]>=0)&(q[is_input]<(1<<21)))
np.savez_compressed(r/'result.npz',coords=coords,original_ids=ids,quantized_coords=q,cluster_id=clusters,class_id=classes,reference_id=reference,v12_input_mask=is_input,background_mask=background)
rows_meta=[]
for node in selected:
 ix=np.flatnonzero(clusters==node);xyz=coords[ix];rows_meta.append({'native_node_id':int(node),'point_count':len(ix),'label':'Candidat '+str(len(rows_meta)+1),'min_m':xyz.min(0).tolist(),'max_m':xyz.max(0).tolist()})
view={'order_displayed':3,'readout':'native continuous component at closed cut, represented by union of strong P_b incidences existing no later than cut; external point coverage, not Hr','radius_m':.04,'cut_radius_squared_quantized_numerator':stats['cut_radius_squared_quantized_numerator'],'cut_radius_squared_quantized_denominator':stats['cut_radius_squared_quantized_denominator'],'cut_rank':stats['cut_rank'],'min_cluster_size_original_points':200,'components_at_cut':len(nodes),'selected_component_count':len(selected),'selected_points':int((classes==1).sum()),'retained_overlap_points':int((cover>1).sum()),'all_coverage_overlap_points':int((components['coverage']>1).sum()),'points_without_any_strong_incidence':int((components['coverage']==0).sum()),'residual_points_unassigned_in_render':int(np.sum(is_input&(classes<0))),'selected_nodes':rows_meta,'class_schema':{'0':'supported by a declared geometric AABB prior; not inferred by HGP','1':'member of a retained native K3 component coverage outside geometric priors; candidate to check','-1':'known surrounding Background or small/uncovered residual, displayed as ignored context'},'cluster_schema':'-1 for context/model-supported points; actual native K3 node ID for candidate points','quantized_coords_dtype':'int32 for full context; only v12_input_mask rows are nonnegative u21 values actually processed'}
(r/'selection_metadata.json').write_text(json.dumps(view,indent=2));print(json.dumps({'result_rows':n,'reference_supported':int((classes==0).sum()),'background':int(background.sum()),'candidates':view['selected_points'],'residual_unassigned':view['residual_points_unassigned_in_render'],'clusters':rows_meta},indent=2))
